```ts
export interface QueueJob {
  jobId: string;
  revision: number;
  urgency: number;
  duration: number;
}

interface IndexedJob {
  job: QueueJob;
  index: number;
}

function compareText(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function readJob(value: unknown): QueueJob | null {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return null;
  }
  const record = value as Record<string, unknown>;
  if (
    typeof record.jobId !== "string" ||
    !Number.isInteger(record.revision) ||
    (record.revision as number) < 0 ||
    !Number.isInteger(record.urgency) ||
    (record.urgency as number) < 0 ||
    (record.urgency as number) > 5 ||
    !Number.isInteger(record.duration) ||
    (record.duration as number) <= 0
  ) {
    return null;
  }
  return {
    jobId: record.jobId,
    revision: record.revision as number,
    urgency: record.urgency as number,
    duration: record.duration as number,
  };
}

function compareVersions(left: IndexedJob, right: IndexedJob): number {
  if (left.job.revision !== right.job.revision) {
    return right.job.revision - left.job.revision;
  }
  if (left.job.urgency !== right.job.urgency) {
    return right.job.urgency - left.job.urgency;
  }
  if (left.job.duration !== right.job.duration) {
    return left.job.duration - right.job.duration;
  }
  return left.index - right.index;
}

export function buildRunQueue(entries: readonly unknown[], capacity: number): QueueJob[] {
  const winners = new Map<string, IndexedJob>();

  entries.forEach((value, index) => {
    const job = readJob(value);
    if (job === null) {
      return;
    }
    const candidate: IndexedJob = { job, index };
    const current = winners.get(job.jobId);
    if (current === undefined || compareVersions(candidate, current) < 0) {
      winners.set(job.jobId, candidate);
    }
  });

  return Array.from(winners.values())
    .sort((left, right) => {
      if (left.job.urgency !== right.job.urgency) {
        return right.job.urgency - left.job.urgency;
      }
      if (left.job.duration !== right.job.duration) {
        return left.job.duration - right.job.duration;
      }
      const byId = compareText(left.job.jobId, right.job.jobId);
      return byId !== 0 ? byId : left.index - right.index;
    })
    .slice(0, capacity)
    .map(({ job }) => ({ ...job }));
}
```

