export class SymbolDocumentDecoder {
    private readonly symbols = new Map<string, string>();

    decode(source: string): string[] {
        const output: string[] = [];

        for (const line of source.split(/\r?\n/)) {
            if (line === "") {
                continue;
            }

            if (line.startsWith("@")) {
                const name = line.slice(1);
                if (!/^[A-Za-z][A-Za-z0-9_]*$/.test(name)) {
                    throw new Error("Invalid reference");
                }
                const value = this.symbols.get(name);
                if (value === undefined && !this.symbols.has(name)) {
                    throw new Error("Undefined symbol");
                }
                output.push(value as string);
                continue;
            }

            const separator = line.indexOf("=");
            if (separator < 0) {
                throw new Error("Invalid definition");
            }
            const name = line.slice(0, separator);
            const value = line.slice(separator + 1);
            if (!/^[A-Za-z][A-Za-z0-9_]*$/.test(name)) {
                throw new Error("Invalid symbol name");
            }
            if (this.symbols.has(name)) {
                throw new Error("Duplicate symbol");
            }
            this.symbols.set(name, value);
        }

        return output;
    }
}
```

